 @Test void publicationPreservesNonemptyFrozenAppointmentBasisWithoutImplementingBooking()throws Exception {
  // Storage fixture only; not UC02 success/acceptance evidence or real patient data.
  var service=new DurationPolicyService(new JdbcTransactions(PgITSupport.config()),PgITSupport.authorization(PgITSupport.grants()),Clock.systemUTC());var c=service.create(UUID.randomUUID(),AuditDocuments.parse("{\"projectName\":\"SYNTHETIC frozen project\",\"durationMinutes\":30}"));long id=c.result().path("targetVersion").path("project_id").longValue();var publish=AuditDocuments.JSON.createObjectNode().put("expectedDraftToken",AuditDocuments.hash(service.version(id,1))).put("reason","SYNTHETIC initial");publish.putNull("expectedCurrentRef");assertEquals("SUCCEEDED",service.publish(UUID.randomUUID(),id,1,publish).businessOutcome());long patient=PgITSupport.next(),appointment=PgITSupport.next();try(var db=PgITSupport.fixture().getConnection();var s=db.createStatement()){s.execute("INSERT INTO adc.patient(patient_id,patient_name,identity_information,contact_information) VALUES("+patient+",'SYNTHETIC storage fixture','SYNTHETIC','SYNTHETIC')");}try(var db=PgITSupport.fixture().getConnection();var p=db.prepareStatement("INSERT INTO adc.appointment(appointment_id,patient_id,schedule_id,schedule_version_no,starts_at,ends_at,treatment_request,manual_confirmation,appointment_status,reminder_arrangement,operated_by,operated_at) VALUES(?,?,9002,1,'2026-11-06T01:00Z','2026-11-06T01:30Z',?,'SYNTHETIC storage fixture','待到诊','SYNTHETIC','SYNTHETIC','2026-11-05T00:00Z')")){p.setLong(1,appointment);p.setLong(2,patient);p.setString(3,AuditDocuments.JSON.createObjectNode().put("fixture","SYNTHETIC FROZEN BASIS").put("projectId",Long.toString(id)).put("versionNo",1).put("durationMinutes",30).toString());p.executeUpdate();}String before=appointmentSnapshot(appointment);long history=PgITSupport.count("SELECT count(*) FROM adc.appointment_change_history");var input=AuditDocuments.JSON.createObjectNode().put("projectId",Long.toString(id)).put("expectedBaseVersion",1).put("projectName","SYNTHETIC new standard").put("durationMinutes",45);assertEquals("SUCCEEDED",service.create(UUID.randomUUID(),input).businessOutcome());var next=AuditDocuments.JSON.createObjectNode().put("expectedDraftToken",AuditDocuments.hash(service.version(id,2))).put("reason","SYNTHETIC replace");next.putObject("expectedCurrentRef").put("projectId",Long.toString(id)).put("versionNo",1);assertEquals("SUCCEEDED",service.publish(UUID.randomUUID(),id,2,next).businessOutcome());assertEquals(before,appointmentSnapshot(appointment));assertEquals(history,PgITSupport.count("SELECT count(*) FROM adc.appointment_change_history"));
 }
 String appointmentSnapshot(long id)throws Exception {try(var c=PgITSupport.app().getConnection();var p=c.prepareStatement("SELECT row_to_json(t)::text FROM adc.appointment t WHERE appointment_id=?")){p.setLong(1,id);try(var r=p.executeQuery()){assertTrue(r.next());return r.getString(1);}}}
 SourceStamp stamp=new SourceStamp("SYNTHETIC-only-isolated-IT","v1","test-reviewer",Instant.EPOCH,true);AtomicReference<List<StaffBindingAdapter.Entry>> entries;MockHttpSession session;MockMvc mvc;
 void grant(Set<String> actions){entries.set(List.of(new StaffBindingAdapter.Entry("synthetic-hq",new StaffAuthorization.Grant("v1",Set.of("HQ"),actions,Set.of(),true),stamp)));}
 @BeforeEach void setup(){entries=new AtomicReference<>(List.of());grant(Set.of("DURATION_EDIT"));var access=new DurationAccessFactory(new JdbcTransactions(PgITSupport.config()),new StaffBindingAdapter(entries::get),()->stamp,Clock.systemUTC());mvc=MockMvcBuilders.standaloneSetup(new DurationController(access)).build();session=new MockHttpSession();session.setAttribute(StaffSessionIdentityAdapter.SESSION_ATTRIBUTE,new StaffSessionIdentityAdapter.VerifiedSession("synthetic-hq","SYNTHETIC-csrf",stamp));}
 @Test void actualMvcToServiceDatabasePublishAndRecoveryWithIndependentGrants()throws Exception {
  String created=mvc.perform(post("/api/v1/headquarters/duration-project-drafts").session(session).header("X-CSRF-Token","SYNTHETIC-csrf").header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content("{\"projectName\":\"SYNTHETIC MVC project\",\"durationMinutes\":30}")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("COMMITTED")).andReturn().getResponse().getContentAsString();var receipt=AuditDocuments.parse(created);String id=receipt.path("versionRef").path("projectId").asText();String raw=mvc.perform(get("/api/v1/staff/duration-projects/"+id+"/versions/1").session(session)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();var publish=AuditDocuments.JSON.createObjectNode().put("expectedDraftToken",AuditDocuments.parse(raw).path("stateToken").asText()).put("reason","SYNTHETIC reviewed");publish.putNull("expectedCurrentRef");String path="/api/v1/headquarters/duration-projects/"+id+"/versions/1/publications";
  mvc.perform(post(path).session(session).header("X-CSRF-Token","SYNTHETIC-csrf").header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(publish.toString())).andExpect(status().isConflict()).andExpect(jsonPath("$.status").value("REJECTED"));grant(Set.of("DURATION_PUBLISH"));String success=mvc.perform(post(path).session(session).header("X-CSRF-Token","SYNTHETIC-csrf").header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(publish.toString())).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();String ref=AuditDocuments.parse(success).path("requestReference").asText();mvc.perform(get("/api/v1/headquarters/duration-commands/"+ref).session(session)).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("COMMITTED"));
 }
 @Test void revokedAuthorityAndSpoofedHeadersCannotCreateRealRowsAndDenialIsAudited()throws Exception {
  mvc.perform(post("/api/v1/headquarters/duration-project-drafts").header("X-Actor","synthetic-hq").header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content("{}" )).andExpect(status().isUnauthorized());entries.set(List.of());String result=mvc.perform(post("/api/v1/headquarters/duration-project-drafts").session(session).header("X-CSRF-Token","SYNTHETIC-csrf").header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content("{\"projectName\":\"SYNTHETIC denied\",\"durationMinutes\":30}")).andExpect(status().isConflict()).andReturn().getResponse().getContentAsString();String ref=AuditDocuments.parse(result).path("requestReference").asText();try(var c=PgITSupport.config().getConnection();var q=c.prepareStatement("SELECT authorization_context->>'decision' FROM adc.extension_operation_audit_event WHERE request_reference=? AND evidence->>'eventKind'='TERMINAL'")){q.setString(1,ref);try(var rows=q.executeQuery()){assertTrue(rows.next());assertEquals("DENY",rows.getString(1));}}
 }
 @Test void rawFloatIsAuditedRejectedAndMissingActivationDoesNotOpenOperations()throws Exception {
  mvc.perform(post("/api/v1/headquarters/duration-project-drafts").session(session).header("X-CSRF-Token","SYNTHETIC-csrf").header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content("{\"projectName\":\"SYNTHETIC invalid\",\"durationMinutes\":1.0}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.auditPersistence").value("CONFIRMED"));var unavailable=new DurationAccessFactory(new JdbcTransactions(PgITSupport.config()),new StaffBindingAdapter(entries::get),()->null,Clock.systemUTC());var closed=MockMvcBuilders.standaloneSetup(new DurationController(unavailable)).build();closed.perform(get("/api/v1/staff/duration-projects").session(session)).andExpect(status().isServiceUnavailable());
 }
